    wp_ch6_title: "6 توكېن ئىقتىسادىي ئەندىزىسى",
    wp_ch6_s1_title: "6.1 توكېن ئەندىزىسى ئەھۋالى",
    wp_ch6_s1_p1: "بۇ پروېكتىمىز توكېن ئىقتىسادىي ئەندىزىسى \"ئالتا ئىقتىدارى مىكسەن مودېلى\"نى ئىپادا قىلىدۇ، سەنئەتتىكى بىرىكمە توكېن ياكى ئىككى توكېن مودېلىنى ئىپادا قىلغان پروېكتلاردىن ئۆزگىرىپ، ئىقتىدارنى ئۆز ئىچىگە ئالغان ئەمەس بىلەن ئېكوسىستېمىسى ئىچىدە قىممەت ئۆز ئىچىگە ئالغان ئەڭ ئېگىشىپ تەقسىملىشىش ئىپادا قىلىدۇ.",
    wp_ch6_s1_p2: "ئالتا توكېن ئەمەس بىر لازىم: قىممەت ئېگىشىش، ھېسابلاش كۈچى ئەگەر، تور سوغۇت، مۈلۈك ئۇنى مەسلىھەت قىلاش، ئەۋەتىش ئەھۋالى، زەنجىرسىمان ئەساس، ئۆز ئىچىگە ئالغان، ئۆز ئىچىگە ئالغان， ئۆز ئىچىگە ئالغان ئىقتىسادىي سىستېمىسىنى قۇرىدۇ.",
    wp_ch6_s1_p3: "بىرىكمە توكېننىڭ ئەگەر ئېكوسىستېمىسىنىڭ پۈتۈن ئىقتىسادىي ئەھۋالىنى ئېگىشىپ، مۇختىلەپ توكېنلار ئەقلىي كونتېرىكى بىلەن ئۆز ئىچىگە ئالغان， ئۆز ئىچىگە ئالغان， ئۆز ئىچىگە ئالغان ۋە ئۆز ئىچىگە ئالغان， ئەڭ ئېگىشىپ ئىقتىسادىي ئىقتىدارىنى ئېگىشىپ.",
    wp_ch6_s1_p4: "تېخنىكا مەناسىدىن، ئالتا توكېن \"ئاساس تىرىكى – ئىچىگى ئىدارىسى – ئىشلەتۈش ئىپادا\" ئۈچ ئەھۋالى ئەندىزىسىنى ئىپادا قىلىدۇ. NEO ئاساس ئەھۋالىنىڭ ئەساس توكېنى بولۇپ， ئېكوسىستېمىسى قىممەت ئېگىشىشى ۋە ئاساس ئۆز ئىچىگە ئالغان ئىقتىدارلىرىنى ئۆز ئىچىگە ئالىدۇ; NEX، NET، NEA ئىچىگى ئىدارىسى ئەندىزىسىنى ئۆز ئىچىگە ئالىدۇ، ئەمەس بىر لازىم: ھېسابلاش كۈچى ئېگىشىپ، تور تەسىرلىيىشى ۋە مۈلۈك ئۇنى مەسلىھەت قىلاش; NRY ۋە NCL ئىشلەتۈش ئىپادا ئەھۋالىنى ئۆز ئىچىگە ئالىدۇ، ئەۋەتىش ئەھۋالى ۋە زەنجىرسىمان قىممەت ئۆز ئىچىگە ئالغان ئىپادا قىلىدۇ.",
    wp_ch6_s1_p5: "ئۈچ ئەھۋالى ئەندىزىسى ئۆز ئىچىگە ئالغان， ئېكوسىستېمىسىنىڭ ئېگىشىش ئەھۋالى، ئىستىقباللىق ئەھۋالى، ئۆزگەرتىش ئەھۋالىدا ئۆز ئىچىگە ئالغان ئىقتىسادىي ئىقتىدارىنى ئېگىشىپ. توكېن ئەندىزىسى ئەگەر \"چىقىرىش ئىتتىقان، ئۆز ئىچىگە ئالغان ئېگىشىپ، تەسىرلىيىش ئېگىشىپ， ئېنېرگىيە تەسىرلىيىشى ئىتتىقان\" ئەساس ئەھۋالىنى ئىپادا قىلىدۇ.",
    wp_ch6_s1_p6: "ئەساس توكېن NEO ئەڭ ئۆزگىرىمىسى ئەھۋالىنى ئىپادا قىلىدۇ، باشقا ئىقتىدارى توكېنلار ئېكوسىستېمىسىنىڭ ئېھتىياجى بىلەن دىستىبۇتلىق ياكى ئىچىگى دىستىبۇتلىق ئەھۋالىنى ئىپادا قىلىدۇ، ئېنېرگىيە تەسۋىرلىمە مەركىزى، ئېگىشىپ قۇلۇپلانغان， ھېسابلاش كۈچى تەسىرلىيىشى قاتارلىق مەركىزىلەر بىلەن توكېن ئېقىمىنى باشقۇرۇپ. بۇلارنىڭ بارلىقى توكېننىڭ چىقىرىشى، تەقسىملىشىشى، ئۆز ئىچىگە ئالغان， تەسۋىرلىمىسى， ئۆز ئىچىگە ئالغان زەنجىرغا ساقلىنىپ， بىرەرسى بىلوكچېين ئىزچىلىسى بىلەن زامانىۋى ئىزدەۋەت， ئىقتىساد مودېلى شەفىق ئىتتىقانى ئېگىشىپ.",
    wp_ch6_s2_title: "6.2 NEO ئەھۋالى",
